def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()
    write_times = {}
    results = []

    for op in ops:
        current_time = op[1]

        # Clean up expired entries
        expired_keys = []
        for key, write_time in write_times.items():
            if current_time >= write_time + ttl:
                expired_keys.append(key)

        for key in expired_keys:
            if key in cache:
                del cache[key]
            del write_times[key]

        if op[0] == 'put':
            key = op[2]
            value = op[3]

            # If key already exists, remove it first (to update its position)
            if key in cache:
                del cache[key]
            # If capacity is full and key is new, evict LRU
            elif len(cache) >= capacity:
                lru_key = next(iter(cache))
                del cache[lru_key]
                del write_times[lru_key]

            # Add the new entry as most recently used
            cache[key] = value
            write_times[key] = current_time

        elif op[0] == 'get':
            key = op[2]

            if key in cache:
                # Move to end (most recently used)
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(-1)

    return results

